scripts.postResponse:
// httpbin echoes what we sent, which is enough to demo the flow.
const echoed = frap.response.json()

frap.test('login returned 200', () => {
  frap.expect(frap.response.status).toBe(200)
})

frap.test('the payload came back intact', () => {
  frap.expect(echoed.json.user).toBe(frap.env.get('USER_ID'))
})

// Pretend the server handed us a token, and persist it to .env.
// Every comment in the file survives this write.
frap.env.set('TOKEN', 'demo-' + echoed.json.user + '-' + Date.now())
frap.console.log('token stored in the active environment')
